INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('e01f8f74-61fe-4d25-b27d-72112e86ecd4', 'a1b2c3d4-2222-4000-8000-000000000002', 1, 'O que é Oração?', 'Redescubrindo o diálogo com Deus', '{"intro": "Santa Teresa de \u00c1vila definiu ora\u00e7\u00e3o como \"um trato de amizade com Aquele que sabemos que nos ama\". N\u00e3o \u00e9 uma f\u00f3rmula m\u00e1gica nem uma lista de pedidos \u2014 \u00e9 um relacionamento. Assim como qualquer amizade, exige tempo, presen\u00e7a e sinceridade. O Catecismo ensina que ora\u00e7\u00e3o \u00e9 a eleva\u00e7\u00e3o da alma a Deus (CIC 2559). Mas antes de elevar, precisamos reconhecer: somos amados antes de orar.", "prayer": "Senhor, ensina-me a rezar. Que eu descubra que antes de eu Te procurar, Tu j\u00e1 me encontraste. Am\u00e9m.", "practice": "Reserve 10 minutos hoje para simplesmente estar na presen\u00e7a de Deus. Sem pedir nada. Sem dizer nada. Apenas estar.", "scripture": "\"Eis que estou \u00e0 porta e bato. Se algu\u00e9m ouvir a minha voz e abrir a porta, entrarei em sua casa e cearei com ele, e ele comigo.\" \u2014 Ap 3,20", "reflection": "Se ora\u00e7\u00e3o \u00e9 amizade, como est\u00e1 sua amizade com Deus hoje? Voc\u00ea fala mais ou escuta mais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('9e816128-a358-40a7-ae0f-8063a050e04f', 'a1b2c3d4-2222-4000-8000-000000000002', 2, 'Oração Vocal', 'As palavras que nos unem ao céu', '{"intro": "A ora\u00e7\u00e3o vocal \u00e9 a forma mais acess\u00edvel de rezar. O Pai Nosso, a Ave Maria, o Gl\u00f3ria \u2014 s\u00e3o ora\u00e7\u00f5es que Jesus e a Igreja nos ensinaram. Mas aten\u00e7\u00e3o: rezar vocalmente n\u00e3o \u00e9 repetir palavras vazias. Jesus alertou contra a \"v\u00e3 repeti\u00e7\u00e3o\" (Mt 6,7). A chave \u00e9 unir l\u00e1bios e cora\u00e7\u00e3o. Santo Agostinho dizia: \"Quem canta, reza duas vezes\". A ora\u00e7\u00e3o vocal \u00e9 porta de entrada para profundidades maiores.", "prayer": "Pai nosso que est\u00e1s nos c\u00e9us... ensina-me a dizer estas palavras n\u00e3o com os l\u00e1bios apenas, mas com toda a minha alma. Am\u00e9m.", "practice": "Reze o Pai Nosso cinco vezes, mas muito devagar. A cada frase, pare e reflita sobre o que est\u00e1 dizendo. Anote qual frase mais tocou seu cora\u00e7\u00e3o.", "scripture": "\"V\u00f3s, pois, orai assim: Pai nosso, que est\u00e1s nos c\u00e9us, santificado seja o teu nome...\" \u2014 Mt 6,9", "reflection": "Qual ora\u00e7\u00e3o vocal voc\u00ea mais reza? Consegue rez\u00e1-la devagar, sentindo cada palavra?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7fca0786-62cd-40f5-bdb5-ef6c0ddd152b', 'a1b2c3d4-2222-4000-8000-000000000002', 3, 'Oração Mental', 'O silêncio que transforma', '{"intro": "A ora\u00e7\u00e3o mental \u00e9 a conversa \u00edntima da alma com Deus \u2014 sem f\u00f3rmulas, sem textos decorados. \u00c9 o cora\u00e7\u00e3o que fala ao Cora\u00e7\u00e3o. Santa Teresa de Jesus dizia que muitos abandonam a ora\u00e7\u00e3o mental por acharem que n\u00e3o sabem fazer \u2014 mas basta \"olhar para Ele que nos olha\". A ora\u00e7\u00e3o mental n\u00e3o exige erudi\u00e7\u00e3o; exige humildade e desejo. Mesmo 5 minutos de ora\u00e7\u00e3o mental valem mais que horas de distra\u00e7\u00e3o.", "prayer": "Jesus manso e humilde de cora\u00e7\u00e3o, fazei o meu cora\u00e7\u00e3o semelhante ao Vosso. Ensina-me o sil\u00eancio que cura e transforma. Am\u00e9m.", "practice": "Sente-se em sil\u00eancio. Feche os olhos. Imagine Jesus sentado ao seu lado. Diga-Lhe o que est\u00e1 no seu cora\u00e7\u00e3o. Depois, fique em sil\u00eancio e escute. 10 minutos.", "scripture": "\"Mas tu, quando orares, entra no teu quarto, fecha a porta e ora a teu Pai em segredo; e teu Pai, que v\u00ea em segredo, te recompensar\u00e1.\" \u2014 Mt 6,6", "reflection": "Voc\u00ea j\u00e1 experimentou o sil\u00eancio interior na ora\u00e7\u00e3o? O que acontece quando voc\u00ea tenta ficar em sil\u00eancio diante de Deus?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('550f63c0-0129-410d-b548-e854e0b1ca80', 'a1b2c3d4-2222-4000-8000-000000000002', 4, 'O Rosário Contemplativo', 'Maria como mestra de oração', '{"intro": "O Ros\u00e1rio n\u00e3o \u00e9 mera repeti\u00e7\u00e3o \u2014 \u00e9 contempla\u00e7\u00e3o dos mist\u00e9rios de Cristo atrav\u00e9s dos olhos de Maria. S\u00e3o Jo\u00e3o Paulo II, em sua enc\u00edclica Rosarium Virginis Mariae, chamou o Ros\u00e1rio de \"comp\u00eandio do Evangelho\". Cada dezena \u00e9 uma janela para um momento da vida de Jesus. O segredo \u00e9 contemplar, n\u00e3o apenas contar. Quando rezado com o cora\u00e7\u00e3o, o Ros\u00e1rio se torna uma escola de ora\u00e7\u00e3o profunda.", "prayer": "Maria, minha M\u00e3e, ensina-me a contemplar teu Filho como tu o contemplavas. Que cada Ave-Maria seja um passo mais perto do Cora\u00e7\u00e3o de Jesus. Am\u00e9m.", "practice": "Reze uma dezena do Ros\u00e1rio (10 Ave-Marias) contemplando um mist\u00e9rio. Antes de come\u00e7ar, leia a passagem b\u00edblica correspondente. Imagine-se na cena.", "scripture": "\"Maria, por\u00e9m, guardava todas estas coisas, meditando-as no seu cora\u00e7\u00e3o.\" \u2014 Lc 2,19", "reflection": "Qual mist\u00e9rio do Ros\u00e1rio mais fala ao seu cora\u00e7\u00e3o hoje? Por que esse mist\u00e9rio te toca?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bee9bcec-b493-48d8-bf5b-8ab8189fe025', 'a1b2c3d4-2222-4000-8000-000000000002', 5, 'Oração de Intercessão', 'Rezar pelos outros como Jesus reza por nós', '{"intro": "Jesus vive para interceder por n\u00f3s (Hb 7,25). Quando rezamos pelos outros, participamos da miss\u00e3o sacerdotal de Cristo. A intercess\u00e3o n\u00e3o \u00e9 informar Deus sobre problemas \u2014 Ele j\u00e1 sabe. \u00c9 unir nosso cora\u00e7\u00e3o ao Dele, carregando juntos o peso do mundo. Santos como Padre Pio recebiam milhares de inten\u00e7\u00f5es e as levavam ao altar. Cada intercess\u00e3o \u00e9 um ato de amor concreto.", "prayer": "Senhor, coloco diante de Ti todos aqueles que carrego no cora\u00e7\u00e3o. Cura, liberta, consola e transforma pela Tua miseric\u00f3rdia. Am\u00e9m.", "practice": "Fa\u00e7a uma lista de 5 pessoas que precisam de ora\u00e7\u00e3o. Reserve 2 minutos para cada uma. Apresente-as a Deus com amor, n\u00e3o com ansiedade.", "scripture": "\"Eu vos digo: Pedi e vos ser\u00e1 dado; buscai e achareis; batei e vos ser\u00e1 aberto.\" \u2014 Lc 11,9", "reflection": "Por quem voc\u00ea sente que Deus est\u00e1 pedindo que reze? H\u00e1 algu\u00e9m que precisa das suas ora\u00e7\u00f5es agora?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('fd5600a3-0646-49ae-b83c-b48815bd4835', 'a1b2c3d4-2222-4000-8000-000000000002', 6, 'Perseverança na Oração', 'Quando Deus parece silencioso', '{"intro": "Todo orante passa pelo deserto \u2014 a \"noite escura\" de S\u00e3o Jo\u00e3o da Cruz. S\u00e3o momentos em que Deus parece ausente, a ora\u00e7\u00e3o parece vazia e o cora\u00e7\u00e3o est\u00e1 seco. Mas \u00e9 justamente a\u00ed que a f\u00e9 se purifica. Madre Teresa de Calcut\u00e1 viveu 50 anos de aridez espiritual \u2014 e nunca deixou de rezar. A perseveran\u00e7a na ora\u00e7\u00e3o n\u00e3o \u00e9 hero\u00edsmo; \u00e9 confian\u00e7a de que Deus est\u00e1 trabalhando no escuro.", "prayer": "Deus fiel, mesmo quando n\u00e3o Te sinto, sei que est\u00e1s aqui. D\u00e1-me a gra\u00e7a de perseverar na ora\u00e7\u00e3o, confiando que Tu ages no sil\u00eancio. Am\u00e9m.", "practice": "Fa\u00e7a um compromisso escrito: \"Eu me comprometo a rezar todos os dias, por pelo menos 10 minutos, durante os pr\u00f3ximos 30 dias \u2014 mesmo quando n\u00e3o sentir vontade.\" Assine e date.", "scripture": "\"Vigia e ora, para que n\u00e3o entreis em tenta\u00e7\u00e3o. O esp\u00edrito est\u00e1 pronto, mas a carne \u00e9 fraca.\" \u2014 Mt 26,41", "reflection": "Voc\u00ea j\u00e1 passou por per\u00edodos de aridez na ora\u00e7\u00e3o? Como reagiu? O que aprendeu com isso?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3301-4000-8000-000000000001', 'b1b2c3d4-3333-4000-8000-000000000003', 1, 'O que é Vocação?', 'Fundamentos do chamado divino', '{"text": "A voca\u00e7\u00e3o n\u00e3o \u00e9 apenas uma profiss\u00e3o ou estado de vida \u2014 \u00e9 o chamado \u00fanico e irrepet\u00edvel que Deus faz a cada pessoa. Santo Tom\u00e1s de Aquino ensina que Deus nos criou com um prop\u00f3sito espec\u00edfico, inscrito em nossa pr\u00f3pria natureza.\n\n\"Deus n\u00e3o nos chama porque somos bons; Ele nos torna bons porque nos chama.\" \u2014 S\u00e3o Jo\u00e3o Cris\u00f3stomo\n\nExistem quatro voca\u00e7\u00f5es fundamentais na Igreja:\n1. **Matrim\u00f4nio** \u2014 chamado \u00e0 santidade conjugal e familiar\n2. **Sacerd\u00f3cio** \u2014 chamado a servir como alter Christus\n3. **Vida Consagrada** \u2014 chamado \u00e0 radicalidade evang\u00e9lica\n4. **Vida Leiga** \u2014 chamado \u00e0 santifica\u00e7\u00e3o no mundo\n\nO discernimento come\u00e7a com a disposi\u00e7\u00e3o de dizer: \"Senhor, o que queres que eu fa\u00e7a?\" (At 9,6)", "scripture": "Jr 1,5 \u2014 Antes de te formar no ventre materno, eu te conheci; antes de sa\u00edres do seio, eu te consagrei."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3302-4000-8000-000000000002', 'b1b2c3d4-3333-4000-8000-000000000003', 2, 'Oração de Entrega', 'Colocar-se diante de Deus', '{"text": "Senhor Jesus Cristo,\nV\u00f3s que me chamais pelo nome,\nque me conheceis antes de eu nascer,\nconcedei-me a gra\u00e7a de ouvir Vossa voz\nno sil\u00eancio do meu cora\u00e7\u00e3o.\n\nTirai de mim todo medo,\ntoda resist\u00eancia,\ntodo apego \u00e0 minha vontade pr\u00f3pria.\n\nQuero apenas o que V\u00f3s quereis para mim.\nFazei de mim instrumento d\u00f3cil\nnas Vossas m\u00e3os.\n\nMaria, M\u00e3e do discernimento,\nque disseste o \"sim\" perfeito,\nintercessora por mim nesta jornada.\n\nAm\u00e9m.", "instruction": "Reze esta ora\u00e7\u00e3o lentamente, em ambiente silencioso. Repita as partes que tocarem seu cora\u00e7\u00e3o."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3303-4000-8000-000000000003', 'b1b2c3d4-3333-4000-8000-000000000003', 3, 'Sinais do Chamado', 'Como Deus fala conosco', '{"text": "Santo In\u00e1cio de Loyola, mestre do discernimento, ensina que Deus nos fala de diversas maneiras:\n\n**1. Consola\u00e7\u00e3o Espiritual**\nUm sentimento profundo de paz, alegria e atra\u00e7\u00e3o por determinado caminho. N\u00e3o \u00e9 euforia passageira, mas uma serenidade duradoura.\n\n**2. Desola\u00e7\u00e3o Espiritual**\nInquieta\u00e7\u00e3o, tristeza, confus\u00e3o \u2014 sinais de que algo n\u00e3o est\u00e1 alinhado com a vontade de Deus.\n\n**3. Mo\u00e7\u00f5es Interiores**\nDesejos persistentes que surgem na ora\u00e7\u00e3o e se confirmam com o tempo.\n\n**4. Sinais Exteriores**\nCircunst\u00e2ncias providenciais, conselhos de diretores espirituais, portas que se abrem ou fecham.\n\n\"Em tempo de desola\u00e7\u00e3o, nunca fazer mudan\u00e7a.\" \u2014 Santo In\u00e1cio\n\nO discernimento requer paci\u00eancia. Deus n\u00e3o tem pressa.", "scripture": "1Rs 19,11-13 \u2014 O Senhor n\u00e3o estava no vento, nem no terremoto, nem no fogo... mas na brisa suave."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3304-4000-8000-000000000004', 'b1b2c3d4-3333-4000-8000-000000000003', 4, 'Reflexão: Minha História Vocacional', 'Olhar para trás para enxergar adiante', '{"text": "Reflita sobre sua hist\u00f3ria pessoal \u00e0 luz do chamado de Deus:\n\n1. **Quais momentos da minha vida me trouxeram maior paz e realiza\u00e7\u00e3o?**\n2. **Quando me senti mais pr\u00f3ximo de Deus?**\n3. **Que talentos e dons recebi que poderiam servir aos outros?**\n4. **H\u00e1 algum desejo persistente no meu cora\u00e7\u00e3o que nunca desaparece?**\n5. **O que as pessoas que me conhecem bem dizem sobre meus dons?**\n\nEscreva suas respostas no di\u00e1rio espiritual. N\u00e3o tenha pressa \u2014 o discernimento \u00e9 um processo.", "prompt": "Descreva um momento em que voc\u00ea sentiu profundamente que Deus estava falando com voc\u00ea. O que aconteceu? Como se sentiu?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3305-4000-8000-000000000005', 'b1b2c3d4-3333-4000-8000-000000000003', 5, 'Modelos de Vocação', 'Santos que discerniram', '{"text": "Grandes santos passaram por intensos processos de discernimento:\n\n**Santo Agostinho** \u2014 Lutou anos entre a vida mundana e o chamado divino at\u00e9 sua convers\u00e3o no jardim de Mil\u00e3o: \"Tarde te amei, \u00f3 Beleza t\u00e3o antiga e t\u00e3o nova!\"\n\n**Santa Teresa de Lisieux** \u2014 Desde crian\u00e7a sentiu o chamado ao Carmelo, mas precisou superar obst\u00e1culos e esperar o tempo de Deus.\n\n**S\u00e3o Francisco de Assis** \u2014 Filho de comerciante rico, ouviu Cristo dizer: \"Francisco, vai e repara minha Igreja.\" Abandonou tudo.\n\n**Santa Madre Teresa de Calcut\u00e1** \u2014 J\u00e1 religiosa, recebeu um \"chamado dentro do chamado\" para servir os mais pobres dos pobres.\n\nCada voca\u00e7\u00e3o \u00e9 \u00fanica. Deus n\u00e3o se repete.", "scripture": "Ef 2,10 \u2014 Somos obra de Deus, criados em Cristo Jesus para as boas obras que Deus de antem\u00e3o preparou para que nelas and\u00e1ssemos."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3306-4000-8000-000000000006', 'b1b2c3d4-3333-4000-8000-000000000003', 6, 'Quiz: Discernimento', 'Teste seus conhecimentos', '{"questions": [{"q": "Segundo Santo In\u00e1cio, o que N\u00c3O se deve fazer em tempo de desola\u00e7\u00e3o?", "correct": 1, "options": ["Rezar mais", "Fazer mudan\u00e7as importantes", "Buscar dire\u00e7\u00e3o espiritual", "Jejuar"]}, {"q": "Qual \u00e9 o primeiro passo do discernimento vocacional?", "correct": 1, "options": ["Pesquisar semin\u00e1rios", "Dispor-se a ouvir a vontade de Deus", "Consultar amigos", "Fazer um retiro"]}, {"q": "Quantas voca\u00e7\u00f5es fundamentais a Igreja reconhece?", "correct": 2, "options": ["2", "3", "4", "5"]}]}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4401-4000-8000-000000000001', 'b1b2c3d4-4444-4000-8000-000000000004', 1, 'O Corpo Revela a Pessoa', 'Introdução à Teologia do Corpo', '{"text": "S\u00e3o Jo\u00e3o Paulo II dedicou 129 audi\u00eancias (1979\u20131984) a desenvolver uma vis\u00e3o revolucion\u00e1ria: o corpo humano n\u00e3o \u00e9 apenas mat\u00e9ria \u2014 \u00e9 uma teologia viva, uma linguagem que revela o mist\u00e9rio de Deus.\n\n**\"O corpo, e somente ele, \u00e9 capaz de tornar vis\u00edvel o que \u00e9 invis\u00edvel: o espiritual e o divino.\"** \u2014 S\u00e3o Jo\u00e3o Paulo II\n\nNo relato da cria\u00e7\u00e3o (Gn 1-2), encontramos tr\u00eas experi\u00eancias origin\u00e1rias:\n\n1. **Solid\u00e3o Original** \u2014 Ad\u00e3o percebe que \u00e9 diferente dos animais; possui autoconsci\u00eancia e liberdade.\n2. **Unidade Original** \u2014 \"Ser\u00e3o os dois uma s\u00f3 carne\" (Gn 2,24). O corpo foi feito para a comunh\u00e3o.\n3. **Nudez Original** \u2014 \"Estavam nus e n\u00e3o sentiam vergonha\" (Gn 2,25). A pureza do olhar antes do pecado.\n\nA Teologia do Corpo n\u00e3o \u00e9 apenas sobre sexualidade \u2014 \u00e9 sobre o significado de ser pessoa.", "scripture": "Gn 1,27 \u2014 Deus criou o ser humano \u00e0 sua imagem; \u00e0 imagem de Deus o criou; homem e mulher os criou."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4402-4000-8000-000000000002', 'b1b2c3d4-4444-4000-8000-000000000004', 2, 'Oração: Contemplar o Dom', 'Agradecer pelo corpo como dom', '{"text": "Senhor Deus,\nV\u00f3s me criastes \u00e0 Vossa imagem e semelhan\u00e7a.\nMeu corpo \u00e9 templo do Esp\u00edrito Santo,\nlinguagem viva do Vosso amor.\n\nAjudai-me a contemplar meu corpo\nn\u00e3o como objeto de vergonha ou idolatria,\nmas como dom sagrado que revela\no mist\u00e9rio da comunh\u00e3o e da entrega.\n\nPurificai meu olhar,\npara que eu veja em cada pessoa\na dignidade inviol\u00e1vel de filho de Deus.\n\nS\u00e3o Jo\u00e3o Paulo II, rogai por n\u00f3s.\nAm\u00e9m.", "instruction": "Reze diante de um crucifixo, contemplando como Cristo entregou Seu corpo por amor."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4403-4000-8000-000000000003', 'b1b2c3d4-4444-4000-8000-000000000004', 3, 'O Significado Esponsal', 'O corpo como dom e entrega', '{"text": "O conceito central da Teologia do Corpo \u00e9 o **significado esponsal do corpo**: a capacidade de expressar amor como doa\u00e7\u00e3o total de si.\n\n**\"O homem n\u00e3o pode viver sem amor. Ele permanece para si mesmo um ser incompreens\u00edvel se o amor n\u00e3o lhe for revelado.\"** \u2014 Redemptor Hominis, 10\n\nO corpo revela que fomos feitos para:\n- **Dar-nos** \u2014 o amor aut\u00eantico \u00e9 sempre dom de si\n- **Receber** \u2014 aceitar o dom do outro com rever\u00eancia\n- **Ser fecundos** \u2014 o amor gera vida, seja biol\u00f3gica ou espiritual\n\nO pecado original distorceu esta linguagem:\n- A **concupisc\u00eancia** reduz a pessoa a objeto\n- A **vergonha** indica a perda da inoc\u00eancia original\n- O **dom\u00ednio** substitui a comunh\u00e3o\n\nMas Cristo veio restaurar o plano original. Na cruz, Ele mostra o significado esponsal em sua plenitude: entrega total, livre, fiel e fecunda.", "scripture": "Ef 5,25 \u2014 Maridos, amai vossas esposas, como Cristo amou a Igreja e se entregou por ela."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4404-4000-8000-000000000004', 'b1b2c3d4-4444-4000-8000-000000000004', 4, 'Reflexão: Meu Corpo como Linguagem', 'Integrar corpo e espírito', '{"text": "S\u00e3o Jo\u00e3o Paulo II nos convida a uma revolu\u00e7\u00e3o interior: ver o corpo como linguagem do amor.\n\nReflita:\n1. **Como eu trato meu corpo?** Com respeito ou neglig\u00eancia?\n2. **Como eu olho para o corpo dos outros?** Com rever\u00eancia ou objetifica\u00e7\u00e3o?\n3. **Minha cultura me ajuda ou atrapalha** a viver a verdade do corpo?\n4. **Em que \u00e1reas da minha vida** preciso de purifica\u00e7\u00e3o do olhar?\n5. **Como posso viver a castidade** como afirma\u00e7\u00e3o do amor, n\u00e3o como repress\u00e3o?\n\nA castidade n\u00e3o \u00e9 dizer \"n\u00e3o\" ao corpo \u2014 \u00e9 dizer \"sim\" ao amor verdadeiro.", "prompt": "Escreva sobre como a cultura atual influencia sua vis\u00e3o do corpo e da sexualidade. Como a Teologia do Corpo pode transformar esse olhar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4405-4000-8000-000000000005', 'b1b2c3d4-4444-4000-8000-000000000004', 5, 'A Ressurreição do Corpo', 'Esperança escatológica', '{"text": "A Teologia do Corpo n\u00e3o termina na morte \u2014 aponta para a ressurrei\u00e7\u00e3o.\n\nQuando os saduceus perguntaram a Jesus sobre o casamento na ressurrei\u00e7\u00e3o, Ele respondeu: \"Na ressurrei\u00e7\u00e3o, nem se casam nem se d\u00e3o em casamento, mas s\u00e3o como anjos no c\u00e9u\" (Mt 22,30).\n\nS\u00e3o Jo\u00e3o Paulo II interpreta: na ressurrei\u00e7\u00e3o, o significado esponsal do corpo ser\u00e1 plenamente realizado \u2014 n\u00e3o no matrim\u00f4nio terreno, mas na **comunh\u00e3o perfeita com Deus**.\n\n**O que isso significa para n\u00f3s agora?**\n- O celibato/virgindade consagrada \u00e9 um sinal antecipado da vida futura\n- O matrim\u00f4nio \u00e9 sacramento que aponta para a uni\u00e3o Cristo-Igreja\n- Toda voca\u00e7\u00e3o \u00e9 chamado ao amor que transcende a morte\n\n\"O corpo glorioso ser\u00e1 a revela\u00e7\u00e3o definitiva da beleza de Deus.\"", "scripture": "1Cor 15,44 \u2014 Semeia-se corpo animal, ressuscita corpo espiritual."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4406-4000-8000-000000000006', 'b1b2c3d4-4444-4000-8000-000000000004', 6, 'Quiz: Teologia do Corpo', 'Teste seus conhecimentos', '{"questions": [{"q": "Quantas audi\u00eancias S\u00e3o Jo\u00e3o Paulo II dedicou \u00e0 Teologia do Corpo?", "correct": 2, "options": ["50", "89", "129", "200"]}, {"q": "Qual \u00e9 o conceito central da Teologia do Corpo?", "correct": 1, "options": ["A proibi\u00e7\u00e3o do prazer", "O significado esponsal do corpo", "A superioridade da alma", "A rejei\u00e7\u00e3o da mat\u00e9ria"]}, {"q": "O que a ''nudez original'' (Gn 2,25) significa teologicamente?", "correct": 1, "options": ["Pobreza material", "Pureza do olhar antes do pecado", "Aus\u00eancia de roupas", "Ingenuidade"]}]}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d96679a4-1535-4692-8929-03959d5fe1c9', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 1, 'O Deserto Interior', NULL, '{"intro": "A m\u00edstica come\u00e7a no sil\u00eancio radical da alma.", "prayer": "Fique 15 minutos em adora\u00e7\u00e3o silenciosa.", "practice": "Desligue as notifica\u00e7\u00f5es do celular por 2 horas.", "reflection": "Onde n\u00e3o h\u00e1 barulho, o Absoluto fala.", "journal_prompt": "Por que voc\u00ea tem medo do sil\u00eancio?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7503cfc8-39a8-4c1b-95ba-b98825aa22dd', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 2, 'A Pobreza de Espírito', NULL, '{"intro": "O apego \u00e0s coisas \u00e9 o peso que impede o voo da alma.", "prayer": "Repita: Eu n\u00e3o sou nada, Tu \u00e9s tudo.", "practice": "Doe algo que voc\u00ea gosta para algu\u00e9m que precise.", "reflection": "S\u00f3 quem nada possui pode possuir Tudo.", "journal_prompt": "O que voc\u00ea ainda tenta segurar com as m\u00e3os fechadas?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
